const draftReportBefore33C=draftReportUpdate;
draftReportUpdate=function(m){
 let html=draftReportBefore33C(m);if(!m?.draftUpdate)return html;
 const d=m.draftUpdate,win=d.difference>0?0:1,lead=d.teams[win],other=d.teams[1-win];
 const reasons=[];
 if(lead.parts.roles>other.parts.roles)reasons.push(...other.details.positions.filter(p=>p.points<0).map(p=>p.hero+': '+p.fit+' позиция ('+Arena33C.signed(p.points)+')'));
 if(lead.parts.counters>other.parts.counters)reasons.push(...lead.details.counters.map(p=>p.hero+' → '+p.target+': '+p.reason));
 if(other.parts.gaps>lead.parts.gaps)reasons.push(...other.details.gaps.map(p=>'У соперника: '+p.label));
 if(lead.parts.synergy>other.parts.synergy)reasons.push(...lead.details.combinations.filter(p=>!other.details.combinations.some(q=>q.label===p.label)).map(p=>p.label+': '+p.heroes.join(' + ')));
 reasons.splice(2);
 const quick='<div class="c-draft-reasons"><b>'+(d.difference?'Что определило преимущество':'Оценки драфтов равны')+'</b>'+(d.difference?'<ul>'+reasons.map(p=>'<li>'+esc(p)+'</li>').join('')+'</ul>':'<p>Бафф и штраф отсутствуют.</p>')+'</div>';
 html=html.replace('<div class="draft-sides">',quick+'<div class="draft-sides">');
 let i=0;html=html.replace(/class="draft-rating"/g,()=>{const n=d.bonuses[i++];return 'class="draft-rating '+(n>0?'positive':n<0?'negative':'neutral')+'"';});
 i=0;html=html.replace(/<ol class="draft-picks">/g,()=>draftCapabilities33C(d.teams[i++])+'<ol class="draft-picks">');
 return html.replace(/class="draft-pick-value"/g,'class="draft-pick-value" title="Поправка за выбранную позицию" aria-label="Поправка за позицию"');
};
